import test from 'node:test';import assert from 'node:assert/strict';
import {newAfternoonScenario,save,restore} from './simulation.js';import {personalEventsAt,beginPersonalEvent,progressPersonalEvent,pausePersonalEvent,personalEventRecord,personalEventView,iseoEventLocation,personalEventGreeting} from './personal-events.js';import {currentSchedule} from './days.js';import {mapEventsAt} from './map-events.js';import {displayName} from './identity.js';
function ready(id,minute=780){const s=newAfternoonScenario('close');s.location=id==='taei'?'cafe':id==='iseo'?'gym':'hall';s.clock.minute=id==='iseo'?960:minute;return s;}
function complete(id,first,second){let s=beginPersonalEvent(ready(id),id);s=progressPersonalEvent(s,first);s=progressPersonalEvent(restore(save(s)),second);return s;}
test('five characters have actual two-stage events with time and persistent non-repeatable completion',()=>{for(const [id,a,b] of [['taei','honest','record'],['yeogyeong','compare','share'],['seoyeon','ask','boundary'],['soyul','permission','wait'],['iseo','introduce','pace']]){let s=ready(id),start=s.clock.minute;s=beginPersonalEvent(s,id);assert.equal(s.clock.minute,start);s=progressPersonalEvent(s,a);assert.equal(s.clock.minute,start+10);assert.equal(personalEventRecord(s).stage,1);s=progressPersonalEvent(restore(save(s)),b);assert.equal(s.clock.minute,start+30);assert.equal(personalEventRecord(s).status,'completed');assert.ok(s.memory.at(-1));assert.ok(!personalEventsAt(s).some(e=>e.person===id));assert.throws(()=>progressPersonalEvent(s,b));}});
test('personal map markers respect identity, current NPC positions, class conflicts and future appointments',()=>{const s=newAfternoonScenario();s.location='hall';assert.equal(personalEventsAt(s).length,0);const known=ready('seoyeon');assert.ok(mapEventsAt(known,'hall').some(e=>e.kind==='personal'&&e.id==='seoyeon'));assert.ok(!personalEventsAt(known,'library').some(e=>e.person==='seoyeon'));known.appointments.push({person:'seoyeon',day:1,status:'pending',minute:790});assert.ok(!personalEventsAt(known).some(e=>e.person==='seoyeon'));});
test('a short conversation reserves the real person, pause releases them, resume keeps choices',()=>{let s=ready('seoyeon',830);s=beginPersonalEvent(s,'seoyeon');s=progressPersonalEvent(s,'ask');assert.equal(currentSchedule(s).seoyeon,'hall');s=pausePersonalEvent(s);assert.equal(currentSchedule(s).seoyeon,'cafe');s.location='cafe';s=beginPersonalEvent(restore(save(s)),'seoyeon');assert.equal(personalEventRecord(s).stage,1);assert.deepEqual(personalEventRecord(s).choices,['ask']);s=progressPersonalEvent(s,'boundary');assert.equal(personalEventRecord(s).status,'completed');});
test('bond and mood change reactions and intrusive solutions are not the best outcome',()=>{let close=beginPersonalEvent(ready('soyul'),'soyul');close=progressPersonalEvent(close,'listen');const distant=ready('soyul');distant.relations['soyul>taei']={familiarity:0,trust:0};const alt=progressPersonalEvent(beginPersonalEvent(distant,'soyul'),'listen');assert.notEqual(personalEventRecord(close).last.text,personalEventRecord(alt).last.text);const patient=complete('yeogyeong','compare','share'),blunt=complete('yeogyeong','pay','share');assert.ok(patient.relations['yeogyeong>taei'].trust>blunt.relations['yeogyeong>taei'].trust);assert.notEqual(patient.lastResult,blunt.lastResult);});
test('Iseo meets through her workout route and learns names only through an actual introduction choice',()=>{let s=ready('iseo');assert.equal(iseoEventLocation(s),'gym');assert.ok(!s.contacts.iseo);const events=personalEventsAt(s);assert.ok(events.some(e=>e.person==='iseo'&&e.title==='운동을 마친 학생'));s=beginPersonalEvent(s,'iseo');assert.equal(displayName(s,'iseo'),'흰 집업을 입은 단발머리 학생');s=progressPersonalEvent(s,'listen');assert.equal(s.contacts.iseo.introduced,false);assert.ok(personalEventView(s).options.some(x=>x[0]==='names'));s=progressPersonalEvent(s,'names');assert.equal(displayName(s,'iseo'),'정이서');assert.equal(s.contacts.iseo.details.major,'태권도과');assert.equal(s.contacts.iseo.playerSeniorityKnown,false);});
test('an interrupted reservation cannot be overrun without resuming',()=>{let s=beginPersonalEvent(ready('seoyeon'),'seoyeon');s=progressPersonalEvent(s,'ask');s.clock.minute+=10;assert.throws(()=>progressPersonalEvent(s,'boundary'));s=pausePersonalEvent(s);s=beginPersonalEvent(s,'seoyeon');s=progressPersonalEvent(s,'boundary');assert.equal(personalEventRecord(s).status,'completed');});
test('stale locations and invalid choices reject without mutation; later references are sourced and limited',()=>{let s=beginPersonalEvent(ready('soyul'),'soyul');s.location='market';const original=save(s);assert.throws(()=>progressPersonalEvent(s,'listen'));assert.equal(save(s),original);s=complete('soyul','permission','wait');assert.equal(personalEventGreeting(s,'soyul'),'');s.day=2;assert.match(personalEventGreeting(s,'soyul'),/지난번|그때/);assert.equal(personalEventGreeting(s,'soyul'),'');});
